async function api(path, body, method) {
  const response = await fetch(`/api${path}`, { method: method || (body ? 'POST' : 'GET'), headers: body ? { 'Content-Type': 'application/json' } : {}, credentials: 'same-origin', ...(body ? { body: JSON.stringify(body) } : {}) });
  const result = await response.json();
  if (!response.ok) { const error = new Error(result.error || 'Please try again.'); error.status = response.status; throw error; }
  return result;
}
function useRoute() {
  const [path, setPath] = useState(location.pathname + (location.pathname.startsWith('/app') ? location.search : ''));
  useEffect(() => { const handler = () => setPath(location.pathname + (location.pathname.startsWith('/app') ? location.search : '')); addEventListener('popstate', handler); return () => removeEventListener('popstate', handler); }, []);
  const navigate = path => { history.pushState({}, '', path); setPath(path); scrollTo(0, 0); };
  return [path, navigate];
}
