const time = value => new Date(value).toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit', timeZone: 'Asia/Kolkata' });
const indiaInput = value => new Date(new Date(value).getTime() + 19800000).toISOString().slice(0, 16);
const indiaDate = () => indiaInput(new Date().toISOString()).slice(0, 10);
